// ===== Personajes nuevos (oct-2026): Ale (pudín), Gochi, Shey, Yaki (rollito de canela) y el chanchito de ahorro. =====
// Son las imágenes originales tal cual (cuadradas, 360 px). Pix.sprite las devuelve del mismo tamaño que los dibujos de 20x20.
(function () {
const ART = {
  pudin: 'data:image/png;base64,',
  gochi: 'data:image/png;base64,',
  shey: 'data:image/png;base64,',
  canela: 'data:image/png;base64,',
  pig: 'data:image/png;base64,'
};
['pudin', 'gochi', 'shey', 'canela'].forEach(n => Pix.define(n, { art: ART[n] }));
Pix.define('piggy', { art: ART.pig });
['pudin', 'gochi', 'shey', 'canela'].forEach(n => Pix.sprite(n + '~fresa', 1)); // deja listas las imágenes para los colores especiales Pix.define('alcancia', { art: ART.pig });
// dónde van la ropa y los accesorios en los dibujos nuevos (medido sobre 20)
if (window.App && App.ANCH) Object.assign(App.ANCH, {
  gochi: Object.assign(App.ANCH.gochi || {}, { hx: 10.2, hy: 8, fy: 13.6, ny: 16.6, sprite: 'gochi', name: 'Gochi' }),
  shey: Object.assign(App.ANCH.shey || {}, { hx: 9.8, hy: 8.4, fy: 14.3, ny: 16.9, sprite: 'shey', name: 'Shey' }),
  yaki: Object.assign(App.ANCH.yaki || {}, { hx: 10.1, hy: 3.8, fy: 14, ny: 16.2, sprite: 'canela', name: 'Yaki' }),
  ale: Object.assign(App.ANCH.ale || {}, { hx: 10.7, hy: 6, fy: 14.2, ny: 16.6, sprite: 'pudin', name: 'Ale' })
});
})();
